<?php
namespace App\Http\Requests;
use Illuminate\Foundation\Http\FormRequest;
class StoreRhContratRequest extends FormRequest {public function authorize():bool{return $this->user()?->can('manageContracts')??false;}public function rules():array{return ['employe_id'=>'required|exists:rh_employes,id','numero'=>'required|string|max:50|unique:rh_contrats,numero','type'=>'required|in:CDI,CDD,Stage,Essai,Consultance,Journalier,Autre','date_debut'=>'required|date','date_fin'=>'required_if:type,CDD|nullable|date|after_or_equal:date_debut','periode_essai_jours'=>'nullable|integer|min:0|max:730','heures_hebdomadaires'=>'required|numeric|min:1|max:168','salaire_base'=>'required|numeric|min:0','devise'=>'required|in:CDF,USD','lieu_travail'=>'nullable|string|max:190','statut'=>'required|in:Brouillon,Actif,Suspendu,Terminé,Résilié','observations'=>'nullable|string'];}}
